// AI-written replica write + RTT tracker
class ReplicaWriter {
  void writeAndMeasure(
      String key, String val, Replica store) {
    long startNs = System.nanoTime();
    long writeTs = System.nanoTime();
    // LWW: keeps larger writeTs
    store.putIfNewer(key, val, writeTs);
    long rttNs = System.nanoTime() - startNs;
    metrics.recordRttNanos(rttNs);
  }
}
